SELECT 'core-2026-09-v4','ed-ing-adjectives','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"ed-ing-adjectives","title":"Adjectives ending in -ed and -ing","level":"A2","order":22,"summary":"Distinguish an experienced feeling from something that causes that feeling.","learningGoals":["The experienced feeling","The cause of the feeling","Connect cause and effect"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"The experienced feeling","explanation":"In these adjective pairs, the -ed form describes how someone feels. Context identifies the experiencer.","examples":["The climbers felt exhausted.","The children seemed delighted."]},{"title":"The cause of the feeling","explanation":"The -ing form describes what produces the feeling. A person can also cause a feeling, so do not use a people-versus-things shortcut.","examples":["The climb was exhausting.","An entertaining storyteller can hold our attention."]},{"title":"Connect cause and effect","explanation":"Read who experiences the emotion and what causes it. The two forms belong to the same adjective family but have different roles.","examples":["A confusing instruction leaves a reader confused.","An exciting event leaves spectators excited."]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-ed-ing-adjectives"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."},"chapter":{"introduction":["Many paired adjectives separate an experience from its cause. An -ed adjective commonly describes how someone feels, while the related -ing adjective describes what produces that feeling. The distinction is about meaning, not a rule that people always take -ed and things always take -ing."],"rules":[{"title":"The experienced feeling","explanation":"In these adjective pairs, the -ed form describes how someone feels. Context identifies the experiencer.","examples":["The climbers felt exhausted.","The children seemed delighted.","The speaker was **boring**, so the audience felt **bored**."],"pattern":"I am **bored**. / The lesson is **boring**.","paragraphs":["Ask who experiences the emotion. That experiencer commonly takes the -ed adjective: the confused reader, the interested visitor. The adjective can follow be or come before a noun. It describes a state; it is not automatically a passive sentence just because it ends in -ed."],"id":"ed-ing-adjectives-foundation-1","domain":"modifiers","referenceIds":["bc-ed-ing-adjectives"],"readingVersion":"foundations-2026-09-v2"},{"title":"The cause of the feeling","explanation":"The -ing form describes what produces the feeling. A person can also cause a feeling, so do not use a people-versus-things shortcut.","examples":["The climb was exhausting.","An entertaining storyteller can hold our attention.","I was **surprised** by the **surprising** result."],"pattern":"She is **interested in** it. / It is **interesting**.","paragraphs":["Ask what causes the feeling. That cause commonly takes -ing: a confusing explanation, an interesting question. A person can also be the cause: a boring speaker is a speaker who bores others, not necessarily someone who feels bored."],"id":"ed-ing-adjectives-foundation-2","domain":"modifiers","referenceIds":["bc-ed-ing-adjectives"],"readingVersion":"foundations-2026-09-v2"},{"title":"Connect cause and effect","explanation":"Read who experiences the emotion and what causes it. The two forms belong to the same adjective family but have different roles.","examples":["A confusing instruction leaves a reader confused.","An exciting event leaves spectators excited.","A **tiring** journey left us **tired**."],"pattern":"The **excited** audience watched an **exciting** match.","paragraphs":["The pairing is lexical. Excited/exciting and tired/tiring are useful pairs, but not every word ending in -ed or -ing belongs to this system. The preposition following an adjective is also part of its pattern: interested in, worried about, pleased with."],"id":"ed-ing-adjectives-foundation-3","domain":"modifiers","referenceIds":["bc-ed-ing-adjectives"],"readingVersion":"foundations-2026-09-v2"},{"title":"Contrasts and edge cases","explanation":"An -ing word can also be a verb form: the film is boring me contains a verb and object. The film is boring usually uses an adjective. Context and sentence structure reveal the role. Learn spelling changes with the adjective: worry → worried/worrying, not worryed.","examples":["The speaker was **boring**, so the audience felt **bored**.","I was **surprised** by the **surprising** result.","A **tiring** journey left us **tired**."],"id":"ed-ing-adjectives-foundation-4","domain":"modifiers","referenceIds":["bc-ed-ing-adjectives"],"readingVersion":"foundations-2026-09-v2"},{"domain":"modifiers","id":"participial-adjective-versus-verb","title":"Participles as adjectives or parts of verb phrases","explanation":"An -ed or -ing form can function as an adjective or as part of a verb phrase. Its complements and meaning help identify its role. Some expressions allow both a state and an event reading. Degree modification can suggest adjective status, while an agent by-phrase often supports a passive event reading.","pattern":"The door **was closed**: state or event?","examples":["The story was **very amusing**.","The host was **amusing the children**."],"commonMistakes":["No single surface test settles every case. Do not treat every -ed adjective as a passive verb or every -ing word as present continuous."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["I am **bored**. / The lesson is **boring**.","She is **interested in** it. / It is **interesting**.","The **excited** audience watched an **exciting** match."],"readingVersion":"core-2026-09-v4"},"stage":"2 · Everyday descriptions","prerequisites":["adjective-order"],"readingReferenceIds":["bc-ed-ing-adjectives","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='ed-ing-adjectives'
